"""Generates src/ordinal_names.cpp from pefile's ordlookup tables (MIT license).

    pip install pefile
    python tools/gen_ordinal_names.py src/ordinal_names.cpp

The table exists only so that BinWeaver's imphash equals pefile's (and thus
the imphash values published by common malware-analysis services) for files
importing oleaut32/ws2_32/wsock32 by ordinal.
"""
import sys

import ordlookup
import pefile

HEADER = """// GENERATED by tools/gen_ordinal_names.py from pefile {version} ordlookup.
// Do not edit by hand. Source tables: pefile (https://github.com/erocarrera/pefile),
// Copyright (c) Ero Carrera, MIT license.
//
// Ordinal -> name mappings that pefile uses when computing imphash for DLLs
// commonly imported by ordinal.
#include "internal.hpp"

#include <algorithm>
#include <array>

namespace bw::detail {{
namespace {{
struct OrdinalName {{
    std::uint16_t ordinal;
    const char* name;
}};
"""


def main(out):
    lines = [HEADER.format(version=pefile.__version__)]
    names = []
    for dll, table in sorted(ordlookup.ords.items()):
        ident = dll.decode().replace(".", "_")
        names.append((dll.decode(), ident, len(table)))
        lines.append("constexpr std::array<OrdinalName, %d> k_%s = {{" % (len(table), ident))
        for ordinal in sorted(table):
            lines.append('    {%d, "%s"},' % (ordinal, table[ordinal].decode()))
        lines.append("}};\n")
    lines.append("} // namespace\n")
    lines.append("const char* known_ordinal_name(std::string_view dll_lower, std::uint16_t ordinal) {")
    lines.append("    auto find = [&](const auto& table) -> const char* {")
    lines.append("        auto it = std::lower_bound(table.begin(), table.end(), ordinal,")
    lines.append("                                   [](const OrdinalName& e, std::uint16_t o) { return e.ordinal < o; });")
    lines.append("        return it != table.end() && it->ordinal == ordinal ? it->name : nullptr;")
    lines.append("    };")
    for dll, ident, _ in names:
        lines.append('    if (dll_lower == "%s") return find(k_%s);' % (dll, ident))
    lines.append("    return nullptr;")
    lines.append("}\n")
    lines.append("bool has_ordinal_table(std::string_view dll_lower) {")
    lines.append("    return " + " || ".join('dll_lower == "%s"' % d for d, _, _ in names) + ";")
    lines.append("}\n")
    lines.append("} // namespace bw::detail\n")
    open(out, "w", encoding="utf-8", newline="\n").write("\n".join(lines))


if __name__ == "__main__":
    main(sys.argv[1])
